using FluNET.Prompt;using FluNET.Prompt.Surface;namespace FluNET.Language.Resources;public enum ResourceReadIntent{Get,Load}public enum ResourceCapability{FileRead,NetworkRead,EnvironmentRead,SecretRead,DatabaseRead}public sealed record ResourceProviderContext(ResourceDescriptor Descriptor,string OutputVariable,SurfaceCommandSyntax SurfaceCommand,SurfaceValueSyntax Source,PromptGrammar Grammar,ResourceReadIntent Intent,string?AuthenticationSecret=null);public sealed record ResourceProviderResult(IReadOnlyList<CommandSyntax>Commands,string?ErrorCode=null,string?ErrorMessage=null){public bool IsSuccess=>ErrorCode is null;public static ResourceProviderResult Error(string c,string m)=>new([],c,m);}public interface IResourceProvider{string Id{get;}IReadOnlyList<ResourceCapability>RequiredCapabilities=>[];bool CanHandle(ResourceDescriptor d);ResourceProviderResult LowerRead(ResourceProviderContext c);}public interface IResourceProviderRegistry{IReadOnlyList<IResourceProvider>Providers{get;}IResourceProvider?Resolve(ResourceDescriptor d);}internal sealed record ResourceProviderRegistration(Type ProviderType,Func<IServiceProvider,IResourceProvider>Create);public sealed class ResourceProviderRegistry:IResourceProviderRegistry{private readonly IResourceProvider[]p;internal ResourceProviderRegistry(IServiceProvider s,IEnumerable<ResourceProviderRegistration>r){p=new IResourceProvider[]{new FileResourceProvider(),new HttpResourceProvider(),new EnvironmentResourceProvider(),new SecretResourceProvider(),new SqlResourceProvider()}.Concat(r.Select(x=>x.Create(s))).ToArray();}public IReadOnlyList<IResourceProvider>Providers=>p;public IResourceProvider?Resolve(ResourceDescriptor d){var m=p.Where(x=>x.CanHandle(d)).ToArray();return m.Length switch{0=>null,1=>m[0],_=>throw new LanguageDefinitionException("Resource matches multiple providers.")};}}
internal static class ResourceProviderSyntax{public static PromptToken T(string x,PromptTokenKind k,int s)=>new(x,k,Math.Max(0,s),0);public static CommandSyntax Read(string verb,ResourceProviderContext c,string source,bool auth=false){List<PromptToken>t=[T(verb,PromptTokenKind.Word,c.SurfaceCommand.Span.Start),T($"[{c.OutputVariable}]",PromptTokenKind.Variable,c.Source.Span.Start),T("FROM",PromptTokenKind.Word,c.Source.Span.Start),T($"{{{source}}}",PromptTokenKind.Reference,c.Source.Span.Start)];if(auth&&c.AuthenticationSecret is string secret){t.Add(T("USING",PromptTokenKind.Word,c.Source.Span.Start));t.Add(T($"{{{secret}}}",PromptTokenKind.Reference,c.Source.Span.Start));}return new(t,c.Grammar);}}
public sealed class FileResourceProvider:IResourceProvider{public string Id=>"core.file";public IReadOnlyList<ResourceCapability>RequiredCapabilities=>[ResourceCapability.FileRead];public bool CanHandle(ResourceDescriptor d)=>d.Reference is FileResourceReference;public ResourceProviderResult LowerRead(ResourceProviderContext c){FileResourceReference f=(FileResourceReference)c.Descriptor.Reference;if(f.IsPattern){if(c.Descriptor.Format!=ResourceFormat.Json)return ResourceProviderResult.Error("FLN225","Glob format unsupported.");return new([ResourceProviderSyntax.Read("LOADGLOB",c,f.Path)]);}string v=c.Descriptor.Format switch{ResourceFormat.Csv=>"LOADCSV",ResourceFormat.Xml=>"LOADXML",ResourceFormat.Binary=>"LOADBINARY",ResourceFormat.Image=>"LOADIMAGE",_=>string.Empty};if(v.Length>0)return new([ResourceProviderSyntax.Read(v,c,f.Path)]);string q=c.Descriptor.Format switch{ResourceFormat.Json=>"CONFIG",ResourceFormat.Text=>"TEXT",_=>string.Empty};if(q.Length==0)return ResourceProviderResult.Error("FLN224",$"No decoder for {c.Descriptor.Format}.");return new([new CommandSyntax([ResourceProviderSyntax.T("LOAD",PromptTokenKind.Word,c.SurfaceCommand.Span.Start),ResourceProviderSyntax.T(q,PromptTokenKind.Word,c.Source.Span.Start),ResourceProviderSyntax.T($"[{c.OutputVariable}]",PromptTokenKind.Variable,c.Source.Span.Start),ResourceProviderSyntax.T("FROM",PromptTokenKind.Word,c.Source.Span.Start),ResourceProviderSyntax.T($"{{{f.Path}}}",PromptTokenKind.Reference,c.Source.Span.Start)],c.Grammar)]);}}
public sealed class HttpResourceProvider:IResourceProvider{public string Id=>"core.http";public IReadOnlyList<ResourceCapability>RequiredCapabilities=>[ResourceCapability.NetworkRead];public bool CanHandle(ResourceDescriptor d)=>d.Reference is HttpResourceReference;public ResourceProviderResult LowerRead(ResourceProviderContext c){if(c.Intent!=ResourceReadIntent.Get)return ResourceProviderResult.Error("FLN223","HTTP belongs to GET.");string v=c.Descriptor.Format switch{ResourceFormat.Json=>"GETHTTP",ResourceFormat.Text=>"GETHTTPTEXT",ResourceFormat.Csv=>"GETHTTPCSV",ResourceFormat.Xml=>"GETHTTPXML",ResourceFormat.Binary=>"GETHTTPBINARY",ResourceFormat.Image=>"GETHTTPIMAGE",_=>string.Empty};if(v.Length==0)return ResourceProviderResult.Error("FLN233","No typed HTTP decoder.");return new([ResourceProviderSyntax.Read(v,c,((HttpResourceReference)c.Descriptor.Reference).Uri.ToString(),auth:true)]);}}
public sealed class EnvironmentResourceProvider:IResourceProvider{public string Id=>"core.environment";public IReadOnlyList<ResourceCapability>RequiredCapabilities=>[ResourceCapability.EnvironmentRead];public bool CanHandle(ResourceDescriptor d)=>d.Reference is EnvironmentResourceReference;public ResourceProviderResult LowerRead(ResourceProviderContext c){if(c.Intent!=ResourceReadIntent.Get)return ResourceProviderResult.Error("FLN223","Environment belongs to GET.");return new([ResourceProviderSyntax.Read("GETENV",c,((EnvironmentResourceReference)c.Descriptor.Reference).Name)]);}}
public sealed class SecretResourceProvider:IResourceProvider{public string Id=>"core.secret";public IReadOnlyList<ResourceCapability>RequiredCapabilities=>[ResourceCapability.SecretRead];public bool CanHandle(ResourceDescriptor d)=>d.Reference is SecretResourceReference;public ResourceProviderResult LowerRead(ResourceProviderContext c){if(c.Intent!=ResourceReadIntent.Get)return ResourceProviderResult.Error("FLN307","Secrets belong to GET.");return new([ResourceProviderSyntax.Read("GETSECRET",c,((SecretResourceReference)c.Descriptor.Reference).Name)]);}}
public sealed class SqlResourceProvider:IResourceProvider{public string Id=>"core.sql";public IReadOnlyList<ResourceCapability>RequiredCapabilities=>[ResourceCapability.DatabaseRead];public bool CanHandle(ResourceDescriptor d)=>d.Reference is SqlResourceReference;public ResourceProviderResult LowerRead(ResourceProviderContext c){if(c.Intent!=ResourceReadIntent.Get)return ResourceProviderResult.Error("FLN330","SQL belongs to GET.");return new([ResourceProviderSyntax.Read("GETSQL",c,((SqlResourceReference)c.Descriptor.Reference).Query)]);}}
